import{_ as t,o as s,c as a,a6 as i}from"./chunks/framework.CKIbuWFA.js";const h=JSON.parse('{"title":"Normalisation, lots et lacunes d’événements","description":"","frontmatter":{"title":"Normalisation, lots et lacunes d’événements","docId":"developer.events","translationKey":"developer.events","locale":"fr","audience":"developer","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"caded5529a62e826a91d2deb86936c29c709ac713c2a0cd021f467b1dfa2b6e7","translationRevision":"77fbd47a8e56f8384eb3cd7015f10db4b5c35678d4e1fb59eab078ec62c79064","order":100},"headers":[],"relativePath":"fr/developer/events.md","filePath":"fr/developer/events.md","lastUpdated":1794611623000}'),n={name:"fr/developer/events.md"};function r(l,e,o,d,c,u){return s(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="event-normalization-batches-and-gaps" tabindex="-1">Normalisation, lots et lacunes d’événements <a class="header-anchor" href="#event-normalization-batches-and-gaps" aria-label="Permalink to &quot;Normalisation, lots et lacunes d’événements {#event-normalization-batches-and-gaps}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objectif et prérequis <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objectif et prérequis {#goal-and-prerequisites}&quot;">​</a></h2><p>Consommer les événements LIVE sans double comptage ni confusion entre récupération de présentation et exécution. Comprenez la <a href="./storage.html">persistance</a> et utilisez des fixtures expurgées plutôt que des captures de comptes réels. <code>tiktools-tiktok</code> enveloppe les dépendances verrouillées du signataire/décodeur et exporte des valeurs TikTools stables ; le cœur n’expose pas les objets protobuf comme API applicative.</p><h2 id="follow-the-implemented-pipeline" tabindex="-1">Suivre le pipeline implémenté <a class="header-anchor" href="#follow-the-implemented-pipeline" aria-label="Permalink to &quot;Suivre le pipeline implémenté {#follow-the-implemented-pipeline}&quot;">​</a></h2><p>L’entrée capture le contexte original de connexion créateur/salle avant le travail asynchrone. La normalisation produit les valeurs de discussion, cadeau, mention J’aime, activité sociale et cycle de vie. Le cœur publie les originaux et gère séparément la comptabilisation/les effets. Les processeurs peuvent attacher des éléments dérivés bornés sous <code>event.intel</code> ; les échecs préservent les événements bruts avec des diagnostics dégradés. Les contrats d’automatisation générés décrivent uniquement les champs émis.</p><p>L’identité de rejeu serveur comprend créateur, salle, méthode, type et identifiant de message non nul. Des identifiants manquants ne permettent pas d’établir un rejeu. La comptabilisation des séries de cadeaux utilise l’identité émetteur/cadeau/groupe et des maxima cumulés, afin qu’un paquet final ne récompense pas deux fois la même quantité. Les prix inconnus restent à zéro. Les transitions d’agrégats peuvent permettre un franchissement de seuil avec <code>previous &lt; threshold &lt;= total</code> ; elles ne remplacent pas les originaux publics.</p><h2 id="implement-a-consumer" tabindex="-1">Implémenter un consommateur <a class="header-anchor" href="#implement-a-consumer" aria-label="Permalink to &quot;Implémenter un consommateur {#implement-a-consumer}&quot;">​</a></h2><ol><li>Utilisez les types de <code>src/automation/contracts/generated/</code> ou l’analyseur d’enveloppe métier des widgets à cette frontière.</li><li>Préservez les curseurs de livraison lors de la sérialisation et dédupliquez les chevauchements en réunissant temps réel et rattrapage.</li><li>Traitez les lots ordonnés sans déclencher un rendu réactif par événement.</li><li>Exposez des signaux explicites de lacune/surcharge. Récupérez la présentation avec des pages bornées ou un nouvel instantané, jamais en invoquant à nouveau les points ou actions.</li></ol><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> contracts</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> live-feed-state</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> automation</span></span></code></pre></div><p>La <a href="https://github.com/nglmercer/TikTools-app/tree/remake/crates/tiktools-core/src/contracts" target="_blank" rel="noreferrer">source des contrats Rust</a> génère le registre des événements, schémas et échantillons ; ne reproduisez pas manuellement des tableaux complets de champs.</p><h2 id="expected-result-and-status" tabindex="-1">Résultat attendu et état <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Résultat attendu et état {#expected-result-and-status}&quot;">​</a></h2><p>Le chevauchement est dédupliqué seulement tant que l’événement identifié reste dans le stockage fini actuel. Les files, compteurs, historiques et caches de rejeu restent bornés. Il ne s’agit ni d’une archive illimitée d’événements ni d’une garantie universelle d’exécution unique. L’épuisement de capacité et la persistance indisponible ont des conséquences explicites sur l’état de santé.</p><h2 id="recover-and-verify" tabindex="-1">Récupérer et vérifier <a class="header-anchor" href="#recover-and-verify" aria-label="Permalink to &quot;Récupérer et vérifier {#recover-and-verify}&quot;">​</a></h2><p>Utilisez des fixtures expurgées de cadeaux/émoticônes et testez les paquets de fin de série, identifiants manquants, identités entre salles et lacunes de reconnexion. Consultez la révision du signataire dans le <code>Cargo.toml</code> actuel plutôt que de copier un hachage d’un ancien rapport de fiabilité. Les méthodes distantes inconnues restent inconnues jusqu’à leur ajout délibéré dans la normalisation et les contrats générés.</p><h2 id="operational-details" tabindex="-1">Détails de fonctionnement <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Détails de fonctionnement {#operational-details}&quot;">​</a></h2><p>Les valeurs actuelles (2026-11-13) sont des limites d’implémentation, pas un SLA. L’entrée LIVE contient 2 048 éléments et la file d’effets 128 ; ce ne sont pas des budgets d’octets. Le cycle de vie attend une place. Cadeaux/follows/shares attendent au plus une seconde puis sont retirés avec signalement de lacune ; chat/likes/joins/autres données sont retirés immédiatement en saturation. Consultez <code>droppedCritical</code>, pertes de lots/unités de likes et d’effets : une entrée perdue peut n’avoir jamais exécuté ses effets. Le backfill répare uniquement l’affichage, jamais points ou actions.</p><p>La déduplication conserve au plus 4 096 identités pendant 300 secondes en mémoire du processus, entre reconnexions tant que ce stockage existe. Expiration, éviction, ID absent ou redémarrage retirent cette protection. La protection contre le chevauchement reste limitée à ce cadre.</p><p><code>ui.feed.backfill</code> reçoit <code>{version:1,after:0,limit:64}</code>, avec curseur numérique global et limite 1–512. Consultez <code>oldestCursor</code>, <code>latestCursor</code>, <code>gap</code>, <code>truncated</code> et continuez depuis le dernier curseur reçu. <code>ui.feed.creator</code> utilise <code>{creatorId,streamId,after,limit}</code>, des curseurs textuels par flux/créateur, une limite 1–64 et un budget d’octets. Ne mélangez pas les curseurs. Flux changé/évincé, curseur futur, lacune d’entrée ou <code>CreatorFeedUnavailable</code> imposent une actualisation de la présentation et un signalement d’historique incomplet, jamais une reconstruction des effets.</p><p>TikTok initialise session, salle, catalogue de cadeaux, bundle de signature puis socket. Configuration : <code>TIKTOOLS_TIKTOK_SIGNING_BUNDLE</code>, <code>TIKTOOLS_TIKTOK_BUNDLE_CACHE</code>, <code>TIKTOOLS_TIKTOK_BUNDLE_URL</code>. Valeurs : cinq tentatives, délai initial 2 s plafonné à 30 s. HTTP 429 respecte Retry-After ou un minimum croissant 30–300 s avec jitter, au plus deux reprises pour limitation, avec cooldown conservé après annulation/épuisement. Les autres reprises exigent une panne de transport transitoire. Inspectez <code>Reconnecting { attempt, delay_ms }</code> et l’étape, sans partager cookies ni signatures privées.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> call</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> system.health</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{}&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span></span></code></pre></div>`,20)])])}const m=t(n,[["render",r]]);export{h as __pageData,m as default};
